parameters.functionScript:
if (!Boolean(Noodl.Variables.xano)) {
    console.error('XanoClient does not exist! Check "Setup XanoClient"')
    return
}

if (!Inputs.Endpoint) {
    console.error('No endpoint provided to Xano Request node')
    return
}

Noodl.Variables.xano[Inputs.RequestType](Inputs.Endpoint, Inputs.Data || {}).then(
    (response) => {
        Outputs.Response = response
        Outputs.Success()
    },
    (error) => {
        console.error(error.getResponse())
        Outputs.Failure()
    }
);

if (Boolean(Noodl.Variables.xano)) return

function createStorage() {
    switch (Inputs.StorageType) {
        case 'sessionStorage':
            return new XanoSessionStorage()
        case 'localStorage':
            return new XanoLocalStorage()
        case 'cookie':
            return new XanoCookieStorage()
        case 'object':
            return new XanoObjectStorage()
    }
}
try {
    Noodl.Variables.xano = new XanoClient({
        'apiGroupBaseUrl': Inputs.apiGroupBaseUrl,
        'datasource': (Inputs.datasource||"live"),
        'storage': createStorage()
    });
    Outputs.Success()
} catch (error) {
    console.error(error)
    Outputs.Failure()
}

if ((!Inputs.ApiGroupBaseUrl) || (Inputs.ApiGroupBaseUrl=="")) {
    console.error("The API Group base url is incorrect or empty")
    return
}

Noodl.Variables.xanoApiGroupBaseUrl = Inputs.ApiGroupBaseUrl;
Noodl.Variables.xanoDatasource = Inputs.Datasource || 'live';
Noodl.Variables.xanoAuthSignupPath = Inputs.AuthSignupPath || '/auth/signup';
Noodl.Variables.xanoAuthLoginPath = Inputs.AuthLoginPath || '/auth/login';
Noodl.Variables.xanoAuthMePath = Inputs.AuthMePath || '/auth/me';

Outputs.Success();

if (!Boolean(Noodl.Variables.xano)) {
    console.error('XanoClient does not exist! Check "Setup XanoClient"')
    return
}

const hasAuthToken = Noodl.Variables.xano.hasAuthToken()

if (hasAuthToken) {
    Outputs.Success()
} else {
    console.log('[XanoAuthTokenRefresh] No token registered')
    Outputs.Failure()
}

if (!Boolean(Noodl.Variables.xano)) {
    console.error('XanoClient does not exist! Check "Setup XanoClient"')
    Outputs.Error()
    return
}

// we want to allow "null" bc that is the Xano way of logging out the user
if (Inputs.Token !== null && !Boolean(Inputs.Token)) {
    console.error('No token was passed to "Set Xano Auth Token"')
    Outputs.Error()
}

Noodl.Variables.xano.setAuthToken(Inputs.Token)

const hasAuthToken = Noodl.Variables.xano.hasAuthToken()

if (hasAuthToken) {
    Outputs.Success()
    Outputs.Done()
} else {
    Outputs.Failure()
    Outputs.Done()
}

ttl = Inputs.ttl

if (!Boolean(ttl)) {
    ttl = 3600
} 
// Set the ttl from secondes to milliseconds
ttl = ttl * 1000

Outputs.ttl = ttl

if (Inputs.loggedIn) {

        if (!Boolean(Inputs.Response)) return 

        const responseBody = Inputs.Response.getBody()

        Object.defineProperty(responseBody, "xanoid",
                Object.getOwnPropertyDescriptor(responseBody, "id"));
        delete responseBody["id"]

        responseBody.id = "currentUser"
        responseBody.loggedIn = Inputs.loggedIn

        currUser = Noodl.Object.create({
                id : "currentUser",
                loggedIn:true 
                })

        currUser.setAll(responseBody)

        // Accessing Data : 
        // Noodl.Objects["currentUser"].<name your column>

        // Output common Xano user data
        Outputs.Id = responseBody.id
        Outputs.xanoId = responseBody.xanoid
        Outputs.Email = responseBody.email
        Outputs.loggedIn = true

        // Output full response
        Outputs.userInformation = responseBody

        Outputs.Success()

} else {

        currUser = Noodl.Object.create({
                id : "currentUser" ,
                loggedIn:false
                })

        Outputs.loggedIn = false

        Outputs.Failure()

}

responseBody = Inputs.User.body

Object.defineProperty(responseBody, "xanoid",
        Object.getOwnPropertyDescriptor(responseBody, "id"));
delete responseBody["id"]

responseBody.id = "currentUser"

Noodl.Objects["currentUser"].setAll(responseBody)

// Accessing Data : 
// Noodl.Objects["currentUser"].<name your column>
//console.log(Noodl.Objects["currentUser"].userInformations)

Outputs.Success()
